mapper.select:
SELECT trade_date FROM market_calendar
WHERE (market_code = #{marketCode}
       OR (#{marketCode} = 'CN' AND market_code = 'CN_A'))
  AND trade_date >= #{fromDate}
  AND trade_date <= #{toDate}
  AND is_trading_day = TRUE
ORDER BY trade_date

SELECT * FROM sector_analytics_calculation_run
WHERE formula_code = #{formulaCode} AND formula_version = #{formulaVersion}
  AND parameter_hash = #{parameterHash} AND source_manifest_hash = #{sourceManifestHash}

SELECT * FROM sector_analytics_publication_batch
WHERE provider_code = #{providerCode} AND market_code = #{marketCode}
  AND as_of_date = #{asOfDate} AND window_days = #{windowDays}
  AND momentum_window_days = #{momentumWindowDays}
  AND formula_version = #{formulaVersion} AND parameter_hash = #{parameterHash}
  AND source_manifest_group_hash = #{sourceManifestGroupHash}

SELECT 
FROM sector_analytics_publication_batch p

JOIN (
    SELECT publication.id FROM sector_analytics_publication_batch publication
    WHERE publication.market_code = #{marketCode} AND publication.window_days = #{windowDays}
      AND publication.momentum_window_days = 5
      AND publication.status = 'PUBLISHED'
    ORDER BY publication.as_of_date DESC, publication.id DESC LIMIT #{days}
) recent_publication ON recent_publication.id = p.id
ORDER BY identity.id, p.as_of_date

SELECT 
FROM sector_analytics_publication_batch p

WHERE p.market_code = #{marketCode} AND p.window_days = #{windowDays}
  AND p.momentum_window_days = 5
  AND p.status = 'PUBLISHED' AND identity.id = #{sectorId}
ORDER BY p.as_of_date DESC, p.id DESC LIMIT #{days}
